#else
#define FONTSHAPER__UNUSED(X) (void)(X)
#define FONTSHAPER__RESTRICT __restrict__
#endif
#  define FONTSHAPER__FOR(I, Start, End) for(fontshaper_un I = (Start); I < (End); ++I)
#  ifdef __cplusplus
#    define FONTSHAPER__ZERO {}
#    define FONTSHAPER__ZERO_TYPE(T) T{}
#  else
#    define FONTSHAPER__ZERO {0}
#    define FONTSHAPER__ZERO_TYPE(T) (T){0}
#  endif
#  define FONTSHAPER__MAX(A, B) (((A) < (B)) ? (B) : (A))
#  define FONTSHAPER__MIN(A, B) (((A) < (B)) ? (A) : (B))
#  define FONTSHAPER__IDIV_ROUND_UP(A, B) (((A) + ((B) - 1)) / (B))
#  define FONTSHAPER__ROUND_UP_POW2(A, B) (((A) + ((B) - 1)) & ~((B) - 1))
#  define FONTSHAPER__ARRAY_LENGTH(A) (sizeof(A)/sizeof(*(A)))
#  define FONTSHAPER__POINTER_AFTER(Type, X) ((Type *)((X) + 1))
#  define FONTSHAPER__POINTER_OFFSET(Type, Base, Offset) ((Type *)((char *)(Base) + (Offset)))
#  define FONTSHAPER__POINTER_DIFF32(Pointer, Base) ((fontshaper_u32)((char *)(Pointer) - (char *)(Base)))
#  define FONTSHAPER__POINTER_DIFF(Pointer, Base) ((fontshaper_un)((char *)(Pointer) - (char *)(Base)))
#  define FONTSHAPER__ALIGN_POINTER(Type, Pointer, Align) (Type *)(((fontshaper_un)(Pointer) + ((Align) - 1)) & ~((Align) - 1))
#  define FONTSHAPER__PASTE_1(A, B) A##B
#  define FONTSHAPER__PASTE_0(A, B) FONTSHAPER__PASTE_1(A, B)
#  define FONTSHAPER__PASTE(A, B) FONTSHAPER__PASTE_0(A, B)
#  define FONTSHAPER__IN_SET(X, Set) ((1u << (X)) & (Set))
#  define FONTSHAPER__SET32_0(Arg) | (1u << (Arg)) FONTSHAPER__SET32_1
#  define FONTSHAPER__SET32_1(Arg) | (1u << (Arg)) FONTSHAPER__SET32_0
#  define FONTSHAPER__SET32_0End
#  define FONTSHAPER__SET32_1End
#  define FONTSHAPER__SET32(Args) (0u FONTSHAPER__PASTE(FONTSHAPER__SET32_0 Args, End))
#  define FONTSHAPER__IN_SET64(X, Set) ((1ull << (X)) & (Set))
#  define FONTSHAPER__SET64_0(Arg) | (1ull << (Arg)) FONTSHAPER__SET64_1
#  define FONTSHAPER__SET64_1(Arg) | (1ull << (Arg)) FONTSHAPER__SET64_0
#  define FONTSHAPER__SET64_0End
#  define FONTSHAPER__SET64_1End
#  define FONTSHAPER__SET64(Args) (0u FONTSHAPER__PASTE(FONTSHAPER__SET64_0 Args, End))
#define FONTSHAPER__U32BE(X) fontshaper__ByteSwap32((X))
#define FONTSHAPER__U32LE(X) (X)
#define FONTSHAPER__BIT_WIDTH(Type) (sizeof(Type)*8)

#define FONTSHAPER__DELETED_SORT_KEY 0xFFFFFFFF

