#define FONTSHAPER__GLYPH_FEATURE_MASK ((FONTSHAPER_GLYPH_FLAG_CFAR << 1) - 1)
// In USE, glyphs are mostly not pre-flagged for feature application.
// However, we do want to flag rphf/pref results for reordering, so we want to
// keep all of the flags as usual, and only use these feature flags for filtering.
#define FONTSHAPER__USE_GLYPH_FEATURE_MASK (FONTSHAPER_GLYPH_FLAG_ISOL | FONTSHAPER_GLYPH_FLAG_FINA | FONTSHAPER_GLYPH_FLAG_FIN2 | FONTSHAPER_GLYPH_FLAG_FIN3 | \
                                     FONTSHAPER_GLYPH_FLAG_MEDI | FONTSHAPER_GLYPH_FLAG_MED2 | FONTSHAPER_GLYPH_FLAG_INIT | FONTSHAPER_GLYPH_FLAG_NUMR | \
                                     FONTSHAPER_GLYPH_FLAG_DNOM | FONTSHAPER_GLYPH_FLAG_FRAC)
#define FONTSHAPER__JOINING_FEATURE_MASK (FONTSHAPER_GLYPH_FLAG_ISOL | FONTSHAPER_GLYPH_FLAG_FINA | FONTSHAPER_GLYPH_FLAG_FIN2 | FONTSHAPER_GLYPH_FLAG_FIN3 | \
                                   FONTSHAPER_GLYPH_FLAG_MEDI | FONTSHAPER_GLYPH_FLAG_MED2 | FONTSHAPER_GLYPH_FLAG_INIT)
#define FONTSHAPER__JOINING_FEATURE_TO_GLYPH_FLAG(Feature) (1 << ((Feature) - 1))

