  fontshaper_u32 LookupSubtableCount;
  fontshaper_u32 GposLookupIndexOffset;
  fontshaper_u32 SequentialLookupCount;
  fontshaper_u32 GposFirstLookup;
  // Valid only between final metrics and cleanup; zero is conservative.
  fontshaper_b32 SkipPostGposCleanup;
  fontshaper__gsub_stream Stream;

  fontshaper__glyph_bucket **LookupGlyphBuckets;
  fontshaper__glyph_bucket *FreeGlyphBuckets;
  fontshaper__bucketed_glyph *SortBuffer;
  void *SortMemory;
  fontshaper_un SortCapacity;
  fontshaper_u32 *CompiledSymbols;
